/// [PostQuantumProvider] and [KeccakPrimitive] backed by `package:pqcrypto`.
///
/// Apart from the ML-DSA key check (ml_dsa_expanded.dart, which uses
/// pqcrypto's SHAKE128), this is the only file that imports pqcrypto. Every
/// call into pqcrypto passes randomness generated by this package.
library;

import 'dart:typed_data';

import 'package:pqcrypto/pqcrypto.dart' as pq;

import '../algorithms/algorithms.dart';
import '../encoding/bytes.dart';
import '../errors.dart';
import 'primitives.dart';

/// pqcrypto implementation of ML-KEM, ML-DSA and SLH-DSA.
final class PqcryptoProvider implements PostQuantumProvider {
  const PqcryptoProvider();

  static final _kems = <KemAlgorithm, _PqKem>{};
  static final _sigs = <SignatureAlgorithm, SignaturePrimitive>{};

  @override
  KemPrimitive mlKem(KemAlgorithm algorithm) => _kems.putIfAbsent(
    algorithm,
    () => _PqKem(switch (algorithm) {
      KemAlgorithm.mlKem512 => pq.PqcKem.kyber512,
      KemAlgorithm.mlKem768 => pq.PqcKem.kyber768,
      KemAlgorithm.mlKem1024 => pq.PqcKem.kyber1024,
      KemAlgorithm.xWing => throw const UnsupportedAlgorithmException(
        'X-Wing is composed by the package, not by the PQ provider',
      ),
    }),
  );

  @override
  SignaturePrimitive signature(SignatureAlgorithm algorithm) =>
      _sigs.putIfAbsent(algorithm, () {
        return switch (algorithm) {
          SignatureAlgorithm.mlDsa44 => _PqMlDsa(pq.DilithiumParams.mlDsa44),
          SignatureAlgorithm.mlDsa65 => _PqMlDsa(pq.DilithiumParams.mlDsa65),
          SignatureAlgorithm.mlDsa87 => _PqMlDsa(pq.DilithiumParams.mlDsa87),
          SignatureAlgorithm.slhDsaShake128s => _PqSlhDsa(
            pq.SlhDsaParams.shake128s,
          ),
          SignatureAlgorithm.slhDsaShake128f => _PqSlhDsa(
            pq.SlhDsaParams.shake128f,
          ),
          SignatureAlgorithm.slhDsaShake192s => _PqSlhDsa(
            pq.SlhDsaParams.shake192s,
          ),
          SignatureAlgorithm.slhDsaShake192f => _PqSlhDsa(
            pq.SlhDsaParams.shake192f,
          ),
          SignatureAlgorithm.slhDsaShake256s => _PqSlhDsa(
            pq.SlhDsaParams.shake256s,
          ),
          SignatureAlgorithm.slhDsaShake256f => _PqSlhDsa(
            pq.SlhDsaParams.shake256f,
          ),
        };
      });
}

/// pqcrypto's FIPS 202 implementation (the one its ML-KEM/ML-DSA use).
final class PqcryptoKeccak implements KeccakPrimitive {
  const PqcryptoKeccak();

  @override
  Uint8List sha3_256(List<int> data) =>
      pq.sha3256(data is Uint8List ? data : Uint8List.fromList(data));

  @override
  Uint8List shake256(List<int> data, int outputLength) => pq.shake256(
    data is Uint8List ? data : Uint8List.fromList(data),
    outputLength,
  );
}

final class _PqKem implements KemPrimitive {
  final pq.KyberKem _kem;

  _PqKem(this._kem);

  @override
  int get publicKeyLength => _kem.params.publicKeyBytes;

  @override
  int get secretKeyLength => _kem.params.secretKeyBytes;

  @override
  int get ciphertextLength => _kem.params.ciphertextBytes;

  /// pqcrypto keeps its check private, so it is reimplemented here: every
  /// 12-bit coefficient of `ByteDecode12(ek[0:384k])` must be below
  /// q = 3329, which is equivalent to `ByteEncode12(ByteDecode12(ek)) == ek`.
  @override
  void validatePublicKey(Uint8List publicKey) {
    if (publicKey.length != publicKeyLength) {
      throw const InvalidKeyException('ML-KEM public key has wrong length');
    }
    final packed = publicKeyLength - 32;
    for (var i = 0; i < packed; i += 3) {
      final b0 = publicKey[i], b1 = publicKey[i + 1], b2 = publicKey[i + 2];
      final c0 = b0 | ((b1 & 0x0f) << 8);
      final c1 = (b1 >> 4) | (b2 << 4);
      if (c0 >= 3329 || c1 >= 3329) {
        throw const InvalidKeyException(
          'ML-KEM public key fails modulus check',
        );
      }
    }
  }

  @override
  RawKeyPair generateFromSeed(Uint8List seed) {
    if (seed.length != 64) {
      throw const InvalidInputException('ML-KEM seed must be 64 bytes');
    }
    final (pk, sk) = _kem.generateKeyPair(Uint8List.fromList(seed));
    return (publicKey: pk, secretKey: sk);
  }

  @override
  RawEncapsulation encapsulate(Uint8List publicKey, Uint8List m) {
    if (m.length != 32) {
      throw const InvalidInputException('ML-KEM randomness must be 32 bytes');
    }
    try {
      final (ct, ss) = _kem.encapsulate(publicKey, Uint8List.fromList(m));
      return (ciphertext: ct, sharedSecret: ss);
    } on ArgumentError {
      throw const InvalidKeyException('Invalid ML-KEM encapsulation key');
    } on StateError {
      throw const InvalidKeyException('Invalid ML-KEM encapsulation key');
    }
  }

  @override
  Uint8List decapsulate(Uint8List secretKey, Uint8List ciphertext) {
    if (ciphertext.length != ciphertextLength) {
      throw const MalformedDataException('ML-KEM ciphertext has wrong length');
    }
    try {
      return _kem.decapsulate(secretKey, ciphertext);
    } on ArgumentError {
      throw const InvalidKeyException('Invalid ML-KEM decapsulation key');
    } on StateError {
      throw const InvalidKeyException('Invalid ML-KEM decapsulation key');
    }
  }
}

final class _PqMlDsa implements SignaturePrimitive {
  final pq.DilithiumParams _params;

  _PqMlDsa(this._params);

  @override
  int get publicKeyLength => _params.publicKeyBytes;

  @override
  int get secretKeyLength => _params.secretKeyBytes;

  @override
  int get signatureLength => _params.signatureBytes;

  @override
  int? get seedLength => 32;

  @override
  int get randomnessLength => 32;

  @override
  RawKeyPair generateFromSeed(Uint8List seed) {
    if (seed.length != 32) {
      throw const InvalidInputException('ML-DSA seed must be 32 bytes');
    }
    final (pk, sk) = pq.MlDsa.generateKeyPairSeeded(
      _params,
      Uint8List.fromList(seed),
    );
    return (publicKey: pk, secretKey: sk);
  }

  @override
  int get keyGenerationRandomnessLength => 32;

  @override
  RawKeyPair generate(Uint8List randomness) => generateFromSeed(randomness);

  @override
  Uint8List publicKeyFromSecretKey(Uint8List secretKey) =>
      throw const UnsupportedAlgorithmException(
        'ML-DSA secret keys are checked by the package',
      );

  @override
  Uint8List sign(
    Uint8List secretKey,
    Uint8List message,
    Uint8List context,
    Uint8List randomness,
  ) {
    if (secretKey.length != secretKeyLength) {
      throw const InvalidKeyException('ML-DSA secret key has wrong length');
    }
    if (context.length > 255) {
      throw const InvalidInputException('Signature context exceeds 255 bytes');
    }
    if (randomness.length != 32) {
      throw const InvalidInputException('ML-DSA randomness must be 32 bytes');
    }
    try {
      return pq.MlDsa.sign(
        secretKey,
        message,
        _params,
        ctx: context,
        rnd: randomness,
      );
    } on ArgumentError {
      throw const InvalidKeyException('Invalid ML-DSA secret key');
    }
  }

  @override
  bool verify(
    Uint8List publicKey,
    Uint8List message,
    Uint8List signature,
    Uint8List context,
  ) {
    if (publicKey.length != publicKeyLength ||
        signature.length != signatureLength ||
        context.length > 255) {
      return false;
    }
    try {
      return pq.MlDsa.verify(
        publicKey,
        message,
        signature,
        _params,
        ctx: context,
      );
    } on Object {
      return false;
    }
  }
}

final class _PqSlhDsa implements SignaturePrimitive {
  final pq.SlhDsaParams _params;

  _PqSlhDsa(this._params);

  @override
  int get publicKeyLength => _params.publicKeyBytes;

  @override
  int get secretKeyLength => _params.secretKeyBytes;

  @override
  int get signatureLength => _params.signatureBytes;

  @override
  int? get seedLength => null;

  @override
  int get randomnessLength => _params.n;

  @override
  RawKeyPair generateFromSeed(Uint8List seed) =>
      throw const UnsupportedAlgorithmException(
        'SLH-DSA has no seed form; its private form is the full secret key',
      );

  @override
  int get keyGenerationRandomnessLength => 3 * _params.n;

  /// FIPS 205 Algorithm 18 from [randomness] = `SK.seed || SK.prf ||
  /// PK.seed`.
  @override
  RawKeyPair generate(Uint8List randomness) {
    if (randomness.length != keyGenerationRandomnessLength) {
      throw InvalidInputException(
        'SLH-DSA key generation randomness must be '
        '$keyGenerationRandomnessLength bytes',
      );
    }
    final n = _params.n;
    final (pk, sk) = pq.SlhDsa.generateKeyPairSeeded(
      _params,
      Uint8List.sublistView(randomness, 0, n),
      Uint8List.sublistView(randomness, n, 2 * n),
      Uint8List.sublistView(randomness, 2 * n),
    );
    return (publicKey: pk, secretKey: sk);
  }

  /// A secret key is `SK.seed || SK.prf || PK.seed || PK.root` (n bytes
  /// each) and its public key is `PK.seed || PK.root`. `PK.root`, the root
  /// of the top XMSS tree, is fully determined by `SK.seed` and `PK.seed`.
  /// Recomputing it detects a corrupted or inconsistent key, which [sign]
  /// would otherwise accept and use to produce only signatures that fail
  /// verification.
  @override
  Uint8List publicKeyFromSecretKey(Uint8List secretKey) {
    if (secretKey.length != secretKeyLength) {
      throw const InvalidKeyException('SLH-DSA secret key has wrong length');
    }
    final n = _params.n;
    final (publicKey, recomputed) = pq.SlhDsa.generateKeyPairSeeded(
      _params,
      Uint8List.sublistView(secretKey, 0, n),
      Uint8List.sublistView(secretKey, n, 2 * n),
      Uint8List.sublistView(secretKey, 2 * n, 3 * n),
    );
    try {
      if (!constantTimeEquals(
        Uint8List.sublistView(recomputed, 3 * n),
        Uint8List.sublistView(secretKey, 3 * n),
      )) {
        throw const InvalidKeyException(
          'SLH-DSA secret key is inconsistent: PK.root does not match '
          'SK.seed and PK.seed',
        );
      }
      return publicKey;
    } finally {
      zeroize(recomputed);
    }
  }

  @override
  Uint8List sign(
    Uint8List secretKey,
    Uint8List message,
    Uint8List context,
    Uint8List randomness,
  ) {
    if (secretKey.length != secretKeyLength) {
      throw const InvalidKeyException('SLH-DSA secret key has wrong length');
    }
    if (context.length > 255) {
      throw const InvalidInputException('Signature context exceeds 255 bytes');
    }
    try {
      return pq.SlhDsa.sign(
        secretKey,
        message,
        _params,
        context: context,
        additionalRandomness: randomness,
        allowSlowSigning: true,
      );
    } on ArgumentError {
      throw const InvalidKeyException('Invalid SLH-DSA secret key');
    }
  }

  @override
  bool verify(
    Uint8List publicKey,
    Uint8List message,
    Uint8List signature,
    Uint8List context,
  ) {
    if (publicKey.length != publicKeyLength ||
        signature.length != signatureLength ||
        context.length > 255) {
      return false;
    }
    try {
      return pq.SlhDsa.verify(
        publicKey,
        message,
        signature,
        _params,
        context: context,
      );
    } on Object {
      return false;
    }
  }
}
